 async function transition(o:Order,to:string){const reason=['cancelled','rejected'].includes(to)?prompt('Reason for this action')||'':null;if(['cancelled','rejected'].includes(to)&&(!reason||reason.trim().length<3)){setError('Enter a cancellation or rejection reason (at least 3 characters).');return}await run(async()=>{if(demo){const changed={...o,status:to,payment_status:to==='delivered'?'cod_collected':o.payment_status};storeOrders(orders.map(x=>x.id===o.id?changed:x));setActiveOrder(changed)}else{await rpc('nexora_transition_order',{p_order:o.id,p_to:to,p_reason:reason});await refresh();setActiveOrder(null);setModal(null)}announce(demo?'Demo order updated':'Order updated')})}
