 {modal==='new-address'&&<Modal title="Add delivery address" onClose={()=>setModal('addresses')}><DeliveryAddressForm initialLocation={gps.value} onLocated={gps.accept} busy={busy} onSave={async data=>{setBusy(true);try{const a:Address={...data,id:crypto.randomUUID(),user_id:authLocationId||profile?.id||'demo-user',is_default:addresses.length===0};if(demo&&!authLocationId)setDemoAddresses([...addresses,a]);else{a.id=await rpc<string>('nexora_save_address',{p_address:a});setRealAddresses(old=>[a,...old.filter(row=>row.id!==a.id)])}selectDeliveryAddress(a.id);await refresh(true);setQuote(null);setModal('addresses');announce('Address saved')}finally{setBusy(false)}}}/></Modal>}
